import{_ as i,a0 as l,w as d,s as g,ao as r,I as a,x as e,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"修復 Ubuntu 中的 “Key is stored in legacy trusted.gpg keyring” 問題 | LCTT x X-CMD","titleTemplate":false,"description":"修復 Ubuntu 中的 “Key is stored in legacy trusted.gpg keyring” 問題 | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"修復 Ubuntu 中的 “Key is stored in legacy trusted.gpg keyring” 問題 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"修復 Ubuntu 中的 “Key is stored in legacy trusted.gpg keyring” 問題 | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20221118.0 ⭐️⭐️ Fixing “Key is stored in legacy trusted.gpg keyring” Issue in Ubuntu","title":"修復 Ubuntu 中的 “Key is stored in legacy trusted.gpg keyring” 問題","tag":"202302","desc":""},"relativePath":"202302/20221118.0 ⭐️⭐️ Fixing “Key is stored in legacy trusted.gpg keyring” Issue in Ubuntu.md","filePath":"[post].md"}'),o={name:"202302/20221118.0 ⭐️⭐️ Fixing “Key is stored in legacy trusted.gpg keyring” Issue in Ubuntu.md"};function u(c,s,k,h,y,b){const t=l("Link");return d(),g("div",null,[s[18]||(s[18]=r(`<h1 id="修復-ubuntu-中的-key-is-stored-in-legacy-trusted-gpg-keyring-問題" tabindex="-1">修復 Ubuntu 中的 “Key is stored in legacy trusted.gpg keyring” 問題 <a class="header-anchor" href="#修復-ubuntu-中的-key-is-stored-in-legacy-trusted-gpg-keyring-問題" aria-label="Permalink to “修復 Ubuntu 中的 “Key is stored in legacy trusted.gpg keyring” 問題”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/22/143209ysmxzrasycrxz7wa.jpg" alt=""></p><p>如果你在 Ubuntu 22.04 及以後的版本中使用 PPA 或添加外部倉庫，你有可能會看到這樣的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>W: https://packagecloud.io/slacktechnologies/slack/debian/dists/jessie/InRelease: Key is stored in legacy trusted.gpg keyring (/etc/apt/trusted.gpg), see the DEPRECATION section in apt-key(8) for details.</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/ubuntu-key-is-stored-legacy.png" alt="ubuntu key is stored legacy"></p><p>首先，這不是一個錯誤，而是一個警告信息。警告並不會導致程序停止工作。即使你在更新過程中看到這個警告信息，你也可以繼續升級你的系統。</p><p>如果你不想看到這個警告信息，你可以採取一些手動步驟來擺脱它。</p><p>有兩種方法；正確的方法和快速而不優雅的方法。閲讀這兩種方法，看看你對哪一種感到滿意。</p><h3 id="方法-1-導入密鑰-正確但複雜的方法" tabindex="-1">方法 1：導入密鑰（正確但複雜的方法） <a class="header-anchor" href="#方法-1-導入密鑰-正確但複雜的方法" aria-label="Permalink to “方法 1：導入密鑰（正確但複雜的方法）”">​</a></h3><p>首先，列出所有添加到你係統中的 GPG 密鑰。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-key list</span></span></code></pre></div><p>這將顯示一個存儲在你係統中的巨大的密鑰列表。你在這裏要做的是尋找與警告信息相關的密鑰。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>abhishek@itsfoss:~$ sudo apt-key list</span></span>
<span class="line"><span>[sudo] password for abhishek: </span></span>
<span class="line"><span>Warning: apt-key is deprecated. Manage keyring files in trusted.gpg.d instead (see apt-key(8)).</span></span>
<span class="line"><span>/etc/apt/trusted.gpg</span></span>
<span class="line"><span>--------------------</span></span>
<span class="line"><span>pub   rsa4096 2014-01-13 [SCEA] [expired: 2019-01-12]</span></span>
<span class="line"><span>      418A 7F2F B0E1 E6E7 EABF  6FE8 C2E7 3424 D590 97AB</span></span>
<span class="line"><span>uid           [ expired] packagecloud ops (production key) &lt;abhishek@itsfoss&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pub   rsa4096 2016-02-18 [SCEA]</span></span>
<span class="line"><span>      DB08 5A08 CA13 B8AC B917  E0F6 D938 EC0D 0386 51BD</span></span>
<span class="line"><span>uid           [ unknown] https://packagecloud.io/slacktechnologies/slack (https://packagecloud.io/docs#gpg_signing) &lt;abhishek@itsfoss&gt;</span></span>
<span class="line"><span>sub   rsa4096 2016-02-18 [SEA]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/etc/apt/trusted.gpg.d/audio-recorder-ubuntu-ppa.gpg</span></span>
<span class="line"><span>----------------------------------------------------</span></span>
<span class="line"><span>pub   rsa4096 2015-08-30 [SC]</span></span>
<span class="line"><span>      42EF 41ED 9813 B713 D4F1  F06D 5CF1 2638 ACF9 669F</span></span>
<span class="line"><span>uid           [ unknown] Launchpad PPA for Team audio-recorder</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/etc/apt/trusted.gpg.d/danielrichter2007-ubuntu-grub-customizer.gpg</span></span>
<span class="line"><span>-------------------------------------------------------------------</span></span>
<span class="line"><span>pub   rsa1024 2010-10-08 [SC]</span></span>
<span class="line"><span>      59DA D276 B942 642B 1BBD  0EAC A8AA 1FAA 3F05 5C03</span></span></code></pre></div><p>你要怎麼做？仔細閲讀該信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>W: https://packagecloud.io/slacktechnologies/slack/debian/dists/jessie/InRelease: Key is stored in legacy</span></span></code></pre></div><p>在我的例子中，倉庫有 <code>packagecloud</code>、<code>slacktechnologies</code> 等關鍵詞。它顯示在 <code>apt-key</code> 列表輸出的頂部。在你的情況下，你可能需要滾動一下。</p><p>在這種罕見的情況下，由 Slack 添加的外部倉庫，有兩個 GPG 密鑰。其中一個已經過期，我會忽略它。你可能不會有這樣的情況。</p><p>你應該看到 <code>pub</code> 後一行的最後 8 個字符（不包括空格）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/etc/apt/trusted.gpg</span></span>
<span class="line"><span>--------------------</span></span>
<span class="line"><span>pub   rsa4096 2014-01-13 [SCEA] [expired: 2019-01-12]</span></span>
<span class="line"><span>      418A 7F2F B0E1 E6E7 EABF  6FE8 C2E7 3424 D590 97AB</span></span>
<span class="line"><span>uid           [ expired] packagecloud ops (production key) &lt;abhishek@itsfoss&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pub   rsa4096 2016-02-18 [SCEA]</span></span>
<span class="line"><span>      DB08 5A08 CA13 B8AC B917  E0F6 D938 EC0D 0386 51BD</span></span>
<span class="line"><span>uid           [ unknown] https://packagecloud.io/slacktechnologies/slack (https://packagecloud.io/docs#gpg_signing) &lt;abhishek@itsfoss&gt;</span></span></code></pre></div><p>因此，從 <code>DB08 5A08 CA13 B8AC B917 E0F6 D938 EC0D 0386 51BD</code> 這行中，我將提取最後8個字符 <code>0386 51BD</code>，去掉空格，然後用它來導入 <code>/etc/apt/trusted.gpg.d</code> 目錄下專用文件中的 GPG 密鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-key export 038651BD | sudo gpg --dearmour -o /etc/apt/trusted.gpg.d/slack.gpg</span></span></code></pre></div><p>我在這裏創建了一個新的文件 <code>slack.gpg</code>，以防你沒有注意到它。我把它命名為 <code>slack.gpg</code> 是因為它與我之前安裝的 Slack 應用有關。文件名並不重要，但它對識別有好處。</p><p>如果命令運行成功，你將不會看到任何信息。你可以通過檢查新創建的 gpg 文件是否存在來驗證。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/import-gpg-key-to-trusted-ubuntu.png" alt="import gpg key to trusted ubuntu"></p><p>再次運行更新，現在你應該不會再看到警告信息了。</p><h3 id="方法-2-複製到-trusted-gpd-d-目錄中-快速而不優雅的方法" tabindex="-1">方法 2：複製到 trusted.gpd.d 目錄中（快速而不優雅的方法） <a class="header-anchor" href="#方法-2-複製到-trusted-gpd-d-目錄中-快速而不優雅的方法" aria-label="Permalink to “方法 2：複製到 trusted.gpd.d 目錄中（快速而不優雅的方法）”">​</a></h3><p>如果你覺得手動做上面的事情不舒服，那麼，你可以忽略這個警告信息。我的意思是，忽略它總是一種選擇。</p><p>另一個選擇是把 <code>/etc/apt/trusted.gpg</code> 文件複製到 <code>/etc/apt/trusted.gpg.d</code> 目錄。畢竟，Ubuntu 只是抱怨説它需要 <code>/etc/apt/trusted.gpg.d</code> 目錄下的 GPG 密鑰。</p><p>你仍然要使用終端。打開它並使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cp /etc/apt/trusted.gpg /etc/apt/trusted.gpg.d</span></span></code></pre></div><p>現在，如果你運行更新，你就不會再看到 “Key is stored in legacy trusted.gpg keyring” 的警告信息。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/quick-dirty-way-to-fix-apt-key-stored-legacy.png" alt="quick dirty way to fix apt key stored legacy"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3>`,33)),a("p",null,[s[1]||(s[1]=e("我曾經寫過一篇關於 ",-1)),n(t,{href:"https://itsfoss.com/apt-key-deprecated/"},{default:p(()=>[...s[0]||(s[0]=[e("棄用 apt-key",-1)])]),_:1}),s[2]||(s[2]=e(" 的詳細文章。顯然，那篇文章讓一些讀者感到困惑，因此我寫了這篇文章，給他們提供擺脱該信息的直接步驟。",-1))]),s[19]||(s[19]=a("p",null,[e("正如我之前所説，這是一個警告信息，目前可以忽略。解決這個問題的責任在於外部軟件開發者和 Ubuntu 開發者。外部軟件開發者應該確保他們的 GPG 密鑰不再被添加到 "),a("code",null,"/etc/apt/trusted.gpg"),e(" 文件中。")],-1)),s[20]||(s[20]=a("p",null,"終端用户不應該為他們的懶惰而承擔痛苦。",-1)),s[21]||(s[21]=a("p",null,"那麼，你是用哪種方法來擺脱 “key is stored in legacy” 的警告信息的呢？第一個方法還是第二個方法？",-1)),s[22]||(s[22]=a("hr",null,null,-1)),a("p",null,[s[4]||(s[4]=e("via: ",-1)),n(t,{href:"https://itsfoss.com/key-is-stored-in-legacy-trusted-gpg/"},{default:p(()=>[...s[3]||(s[3]=[e("https://itsfoss.com/key-is-stored-in-legacy-trusted-gpg/",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=e("作者：",-1)),n(t,{href:"https://itsfoss.com/"},{default:p(()=>[...s[5]||(s[5]=[e("Abhishek Prakash",-1)])]),_:1}),s[10]||(s[10]=e(" 選題：",-1)),n(t,{href:"https://github.com/lkxed"},{default:p(()=>[...s[6]||(s[6]=[e("lkxed",-1)])]),_:1}),s[11]||(s[11]=e(" 譯者：",-1)),n(t,{href:"https://github.com/geekpi"},{default:p(()=>[...s[7]||(s[7]=[e("geekpi",-1)])]),_:1}),s[12]||(s[12]=e(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:p(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[e("Linux中國",-1)])]),_:1}),s[17]||(s[17]=e(" 榮譽推出",-1))])])}const x=i(o,[["render",u]]);export{C as __pageData,x as default};
